// How DNA works, per reply topic: fact lines generated by code from the contract constants (scripts/brain-context.ts
// writes brain/mechanics.json), so a reply may state their numbers. The launch guard's lines only on a hook that has it.
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { mechanics } from "../scripts/brain-context.ts";
import { ENCLAVE } from "../src/enclave.ts";
import { MECHANICS, mechanicsFor, TOPICS } from "../src/mechanics.ts";
import { factNumbers, postFilter } from "../src/voice.ts";

test("mechanics: generated, committed fresh, one block per topic", () => {
  assert.deepEqual(JSON.parse(readFileSync(new URL("../brain/mechanics.json", import.meta.url), "utf8")), mechanics());
  execFileSync(process.execPath, ["scripts/brain-context.ts", "--check"], { cwd: new URL("..", import.meta.url).pathname, env: { PATH: process.env.PATH ?? "" }, stdio: "pipe" });
  for (const t of ["hook_fee", "launch_guard", "buyback_burn", "liquidity_lock", "fee_split", "veto_safe", "idea_market", "games", "proof_enclave", "dev_team"] as const) {
    assert.ok(TOPICS.includes(t), t);
    assert.ok(MECHANICS[t].length >= 2, t);
  }
});

test("mechanics: the numbers are the contracts' own", () => {
  const all = (t: keyof typeof MECHANICS) => MECHANICS[t].join(" ");
  assert.match(all("hook_fee"), /never charges more than 5%/);
  assert.match(all("hook_fee"), /\b0\.3%/);
  assert.match(all("fee_split"), /35% to buyback-and-burn, 35% to liquidity, 30% to the treasury/);
  assert.match(all("veto_safe"), /at least 1 hour/);
  assert.match(all("idea_market"), /24 hours/);
  assert.match(all("games"), /10 winners/);
  assert.match(all("launch_guard"), /90%/);
  assert.match(all("launch_guard"), /20,000,000 DNA/);
});

test("mechanics: every line is postable as written (no number words, links or banned terms) and its numbers become allowed", () => {
  ENCLAVE.on = true; // the enclave's lines post only from the enclave
  try {
    for (const [t, lines] of Object.entries(MECHANICS)) {
      for (const l of lines) {
        const facts = { mechanics: [l] };
        assert.deepEqual(postFilter(l, factNumbers(facts)).filter((i) => i !== "over 280 weighted chars"), [], `${t}: ${l}`);
      }
    }
    assert.equal(mechanicsFor("proof_enclave", false), MECHANICS.proof_enclave);
  } finally { ENCLAVE.on = false; }
  assert.deepEqual(mechanicsFor("proof_enclave", false), [], "the plain build claims no enclave");
  assert.ok(factNumbers({ mechanics: ["at most 20,000,000 DNA and 0.3%"] }).has("20000000"));
  assert.ok(factNumbers({ mechanics: ["at most 20,000,000 DNA and 0.3%"] }).has("0.3"));
  assert.ok(!factNumbers({ question: "is it 99%" }).has("99"), "only mechanics strings lend numbers");
});

test("mechanics: the launch guard only on a hook that has it; status and other topics have no block", () => {
  assert.deepEqual(mechanicsFor("launch_guard", false), []);
  assert.deepEqual(mechanicsFor("launch_guard", true), MECHANICS.launch_guard);
  const where = [MECHANICS.fee_split[0], MECHANICS.buyback_burn[1]];
  assert.deepEqual(mechanicsFor("hook_fee", false), [...MECHANICS.hook_fee, ...where], "the fee topic tells where the fee goes and the buyback's pace");
  assert.match(mechanicsFor("hook_fee", false).join(" "), /35% to buyback-and-burn.*1 buy every 1 hour/);
  assert.deepEqual(mechanicsFor("hook_fee", true).slice(MECHANICS.hook_fee.length, -2), MECHANICS.launch_guard, "the fee topic tells the guard too when it is there");
  assert.deepEqual(mechanicsFor("other", true), []);
  assert.deepEqual(mechanicsFor("status_wen", true), []);
});
